```java
import java.io.*;
import java.util.HashSet;
import java.util.Set;

// This class demonstrates a secure way to handle data through data validation
public class SecureServer {
    public void processRequest(InputStream inputStream) throws IOException {
        // Instead of full object deserialization, we use a safe alternative 
        // like JSON or a strictly typed data format.
        // Here, we simulate a "Whitelist" approach for a safe data format.

        // For demonstration, we use a simple Data Transfer Object (DTO) 
        // and avoid reading raw ObjectInputStream to prevent RCE.
        BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream));
        String line = reader.readLine();

        if (line != null && isValidData(line)) {
            // Only process the specific, expected data types
            System.out.println("Safely processed data: " + line);
        } else {
            throw new SecurityException("Invalid or unauthorized data format detected!");
        }
    }

    private boolean isValidData(String data) {
        // Implement strict validation logic (e.g., regex or type checking)
        // to ensure only expected patterns are processed.
        return data.matches("^[a-zA-Z0-9 ]*$");
    }
}
